mapper.sql:
WHERE sales_orders.status != -1
AND sales_orders.is_pos = 0
AND sales_orders.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})
AND sales_orders.location_group_id IN (SELECT location_group_id FROM user_location_groups WHERE user_id =  #{userId})

    AND (
    sales_orders.so_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND sales_orders.order_date >= #{filter.dateFrom}


    AND sales_orders.order_date <= #{filter.dateTo}


    AND sales_orders.status = #{filter.status}


    AND sales_orders.`type` = #{filter.type}


    AND sales_orders.company_id = #{filter.companyId}


    AND sales_orders.location_group_id = #{filter.warehouseId}


    AND sales_orders.customer_id = #{filter.organizationId}


    AND sales_orders.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})


    AND sales_orders.created_by = #{filter.createdBy}


    AND sales_orders.is_none_vat = #{filter.filterBy}


    AND sales_orders.ut_system_type_id  = #{filter.departmentId}

mapper.select:
SELECT sales_orders.id AS id, sales_orders.order_date AS invoiceDate, sales_orders.so_code AS invoiceCode, (SELECT GROUP_CONCAT(cgroups.name SEPARATOR ', ') FROM cgroups WHERE cgroups.is_active = 1 AND cgroups.id IN (SELECT cgroup_id FROM customer_cgroups WHERE customer_cgroups.customer_id = sales_orders.customer_id) ) AS organizationGroupName, COALESCE( (SELECT GROUP_CONCAT(products.name SEPARATOR ', ') FROM products WHERE products.is_active = 1 AND products.id IN (SELECT product_id FROM sales_order_details WHERE sales_order_details.sales_order_id = sales_orders.id)), (SELECT GROUP_CONCAT(services.name SEPARATOR ', ') FROM services WHERE services.is_active = 1 AND services.id IN (SELECT service_id FROM sales_order_services WHERE sales_order_services.sales_order_id = sales_orders.id)), (SELECT GROUP_CONCAT(sales_order_miscs.description SEPARATOR ', ') FROM sales_order_miscs WHERE sales_order_miscs.sales_order_id = sales_orders.id), '' ) AS description, CONCAT_WS(' ', customers.name) AS organizationName, sales_orders.total_amount - IFNULL(sales_orders.discount, 0) - IFNULL(sales_orders.total_deposit, 0) AS subTotal, IFNULL(sales_orders.total_vat, 0) AS totalVat, sales_orders.total_amount - IFNULL(sales_orders.discount, 0) + IFNULL(sales_orders.total_vat, 0) - IFNULL(sales_orders.total_deposit, 0) AS totalAmount, sales_orders.balance AS balance, IF(balance > 0 AND DATEDIFF(now(), due_date) > 0, DATEDIFF(now(), due_date), '.') AS aging, sales_orders.status AS status, currency_centers.symbol AS currencySymbol FROM sales_orders INNER JOIN customers ON customers.id = sales_orders.customer_id INNER JOIN currency_centers ON currency_centers.id = sales_orders.currency_center_id
ORDER BY sales_orders.order_date DESC, sales_orders.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT customers.id AS id, (SELECT GROUP_CONCAT(cgroups.name SEPARATOR ', ') FROM cgroups WHERE cgroups.is_active = 1 AND cgroups.id IN (SELECT cgroup_id FROM customer_cgroups WHERE customer_cgroups.customer_id = sales_orders.customer_id) ) AS organizationGroupName, CONCAT_WS(' ', customers.name) AS organizationName FROM sales_orders INNER JOIN customers ON customers.id = sales_orders.customer_id INNER JOIN currency_centers ON currency_centers.id = sales_orders.currency_center_id
GROUP BY customers.id ORDER BY sales_orders.order_date ASC, sales_orders.id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}
